const clubList = window.clubDirectory || [];
const clubParams = new URLSearchParams(window.location.search);
const currentClub = clubList.find((club) => club.id === clubParams.get('club')) || clubList[0];
const tabs = [['overview', 'Overview'], ['table', 'Table'], ['fixtures', 'Fixtures'], ['player-stats', 'Player Stats'], ['team-stats', 'Team Stats'], ['history', 'History']];
const esc = (value) => String(value || '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const profileUrl = `club.html?club=${encodeURIComponent(currentClub.id)}&competition=${encodeURIComponent(currentClub.league)}`;
const directoryUrl = `clubs.html?competition=${encodeURIComponent(currentClub.league)}`;
const badge = (club, className = '') => `<img class="${className}" src="${club.image}" alt="${esc(club.name)} badge" loading="lazy" />`;
const competitionBadge = (club) => `<img src="${club.logo}" alt="${esc(club.leagueName)} logo" loading="lazy" />`;
const findClub = (name) => clubList.find((club) => club.league === currentClub.league && club.name === name) || clubList.find((club) => club.name === name) || currentClub;
document.documentElement.style.setProperty('--club-accent', currentClub.accent);
document.title = `${currentClub.name} Club Profile - Tanzania Major League`;

const heroRoot = document.querySelector('[data-club-hero]');
heroRoot.innerHTML = `<div class="club-hero-layout"><div class="club-hero-badge">${badge(currentClub)}</div><div class="club-hero-identity"><a class="club-hero-tag" href="${directoryUrl}">${competitionBadge(currentClub)}<span>${esc(currentClub.leagueName)}</span></a><h1>${esc(currentClub.name)}<br /><em>club.</em></h1><p>${esc(currentClub.name)} represents ${esc(currentClub.city)} with a clear identity, a proud home ground and a season built around the next result.</p><div class="club-hero-meta"><span>Founded <b>${currentClub.founded}</b></span><span>City <b>${esc(currentClub.city)}</b></span><span>Coach <b>${esc(currentClub.coach)}</b></span><span>Colors <b>${esc(currentClub.colors)}</b></span></div><a class="club-hero-back" href="${directoryUrl}">&larr; Back to ${esc(currentClub.leagueName)} clubs</a></div><div class="club-hero-position"><small>Current league position</small><strong>${String(currentClub.position).padStart(2, '0')}</strong><span>2026 / 2027 season</span></div></div>`;

const tabsRoot = document.querySelector('[data-club-tabs]');
tabsRoot.innerHTML = tabs.map(([id, label]) => `<a class="club-profile-tab" href="#${id}" data-profile-tab="${id}">${label}</a>`).join('');

const panelTitle = (kicker, title, note = '') => `<div class="profile-panel-heading"><div><p class="section-kicker">${kicker}</p><h2>${title}</h2></div>${note ? `<p class="profile-panel-note">${note}</p>` : ''}</div>`;
const recentMatches = currentClub.fixtures.filter((fixture) => fixture.status === 'FT').slice(0, 5);
const nextMatch = currentClub.fixtures.find((fixture) => fixture.status === 'Upcoming') || currentClub.fixtures[0];

document.querySelector('[data-club-overview]').innerHTML = `${panelTitle('01 / THE CLUBHOUSE', 'Club <em>overview.</em>', `${currentClub.leagueName} / 2026-27`)}<div class="club-overview-grid"><article class="profile-card overview-summary"><h3>The badge <em>in context.</em></h3><p>${esc(currentClub.name)} is a ${esc(currentClub.city)} club competing in the ${esc(currentClub.leagueName)}. This profile brings the squad, season numbers, matchday rhythm and club history into one place.</p><div class="club-facts-grid"><div class="club-fact"><span>Home stadium</span><b>${esc(currentClub.stadium)}</b></div><div class="club-fact"><span>Club colors</span><b>${esc(currentClub.colors)}</b></div><div class="club-fact"><span>Founded</span><b>${currentClub.founded}</b></div><div class="club-fact"><span>Current position</span><b>#${currentClub.position} / 16</b></div></div><div class="form-block"><span>Recent form</span><div class="form-pills">${currentClub.form.map((result) => `<span class="form-pill ${result === 'W' ? 'win' : result === 'D' ? 'draw' : 'loss'}">${result}</span>`).join('')}</div></div></article><article class="profile-card profile-card-dark"><h3>Quick <em>numbers.</em></h3><p>The season snapshot supporters check first.</p><div class="overview-stat-grid">${[['played', 'Played'], ['wins', 'Wins'], ['draws', 'Draws'], ['losses', 'Losses'], ['goalsFor', 'Goals for'], ['goalsAgainst', 'Goals against'], ['cleanSheets', 'Clean sheets'], ['possession', 'Possession']].map(([key, label]) => `<div class="overview-stat"><strong>${currentClub.stats[key]}${key === 'possession' ? '%' : ''}</strong><span>${label}</span></div>`).join('')}</div></article></div><div class="overview-lower-grid"><article class="profile-card profile-card-dark"><h3>Last five <em>matches.</em></h3><div class="form-results">${recentMatches.map((fixture) => `<div class="form-match"><span>${esc(fixture.date)}</span><span class="form-match-teams">${esc(fixture.home)}<br />${esc(fixture.away)}</span><span class="form-match-score">${esc(fixture.score)}</span></div>`).join('')}</div></article><article class="profile-card"><h3>Next <em>match.</em></h3><div class="next-match"><div class="next-match-date">${esc(nextMatch.date.split(' ')[0])}<small>${esc(nextMatch.date.split(' ').slice(1).join(' '))}</small></div><div class="next-match-info"><strong>${esc(nextMatch.home)}<br />${esc(nextMatch.away)}</strong><span>${esc(nextMatch.time)} / ${esc(nextMatch.venue)}</span></div></div><a class="club-hero-back" style="color:var(--club-accent)" href="#fixtures">See all fixtures &rarr;</a></article><article class="profile-card"><h3>Top <em>scorer.</em></h3><div class="club-scorer"><span class="club-scorer-image">${badge(currentClub.topScorer)}</span><div><strong>${esc(currentClub.topScorer.name)}</strong><span>${esc(currentClub.topScorer.position)} / ${currentClub.topScorer.goals} goals / ${currentClub.topScorer.appearances} appearances</span></div></div></article><article class="profile-card"><h3>Key <em>players.</em></h3><div class="key-players-grid">${currentClub.keyPlayers.map((player) => `<div class="key-player"><span class="key-player-image">${badge(player)}</span><div class="key-player-info"><strong>${esc(player.name)}</strong><span>${esc(player.position)}</span></div></div>`).join('')}</div></article></div><article class="profile-card" style="margin-top:15px"><h3>Latest club <em>news.</em></h3><div class="club-latest-news"><a class="club-news-link" href="news.html?league=${encodeURIComponent(currentClub.league)}">${esc(currentClub.name)} sets the tone for the next matchweek.<small>${esc(currentClub.leagueName)} / Read the latest</small></a><a class="club-news-link" href="news.html?league=${encodeURIComponent(currentClub.league)}">Inside the squad: the numbers behind the current run.<small>${esc(currentClub.city)} / Club notebook</small></a></div></article>`;

const zoneFor = (position) => position <= 2 ? 'caf-champions' : position <= 4 ? 'caf-confederation' : position >= 15 ? 'relegation' : position >= 13 ? 'playoff' : '';
document.querySelector('[data-club-table]').innerHTML = `${panelTitle('02 / THE LADDER', 'Full league <em>table.</em>', `${currentClub.leagueName} / 16 clubs`)}<div class="profile-table-wrap"><table class="profile-table"><thead><tr><th>Pos</th><th>Club</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>GD</th><th>Pts</th></tr></thead><tbody>${currentClub.table.map((row, index) => { const tableClub = findClub(row[0]); const position = index + 1; return `<tr class="${row[0] === currentClub.name ? 'selected-club-row' : ''}"><td><span class="table-zone ${zoneFor(position)}"></span><span class="table-position">${position}</span></td><td><span class="table-club">${badge(tableClub)}${esc(row[0])}</span></td><td>${row[1]}</td><td>${row[2]}</td><td>${row[3]}</td><td>${row[4]}</td><td>${row[5]}</td><td>${row[6]}</td><td>${row[7]}</td><td>${row[8]}</td></tr>`; }).join('')}</tbody></table></div><div class="table-legend"><span class="green">CAF Champions League</span><span class="blue">CAF Confederation Cup</span><span class="orange">Play-off zone</span><span class="red">Relegation zone</span></div>`;

const fixtureClubBadge = (name, side = '') => `<span class="fixture-side ${side}">${badge(findClub(name), 'fixture-club-logo')}<strong class="fixture-team">${esc(name)}</strong></span>`;
document.querySelector('[data-club-fixtures]').innerHTML = `${panelTitle('03 / MATCHDAY', 'Fixtures & <em>results.</em>', `${currentClub.leagueName} / 2026-27`)}<div class="fixture-grid">${currentClub.fixtures.map((fixture) => `<article class="fixture-card${fixture.status === 'FT' ? ' is-finished' : ''}" style="--club-accent:${currentClub.accent}"><div class="fixture-card-top"><span class="fixture-card-date">${esc(fixture.date)} / ${esc(fixture.competition)}</span><span class="fixture-status ${fixture.status === 'FT' ? 'ft' : fixture.status === 'Postponed' ? 'postponed' : ''}">${esc(fixture.status)}</span></div><div class="fixture-teams">${fixtureClubBadge(fixture.home)}<span class="fixture-vs">${fixture.status === 'FT' ? esc(fixture.score) : 'VS'}</span>${fixtureClubBadge(fixture.away, 'away')}</div><div class="fixture-card-bottom"><span>${esc(fixture.venue)}<br />${esc(fixture.time)}</span><strong class="fixture-score">${fixture.status === 'FT' ? esc(fixture.score) : esc(fixture.time)}</strong></div></article>`).join('')}</div>`;

const playersRoot = document.querySelector('[data-club-player-stats]');
const playerFilters = [['All Players', 'All Players'], ['Goalkeeper', 'Goalkeepers'], ['Defender', 'Defenders'], ['Midfielder', 'Midfielders'], ['Forward', 'Forwards']];
function renderPlayers(filter = 'All Players') { const visible = currentClub.players.filter((player) => filter === 'All Players' || player.position === filter); playersRoot.innerHTML = `${panelTitle('04 / THE SQUAD', 'Player <em>stats.</em>', `${visible.length} players shown`)}<div class="player-filters">${playerFilters.map(([value, label]) => `<button class="player-filter${filter === value ? ' active' : ''}" type="button" data-player-filter="${value}">${label}</button>`).join('')}</div><div class="player-table-wrap"><table class="profile-table player-table"><thead><tr><th>Player</th><th>Position</th><th>Apps</th><th>Goals</th><th>Assists</th><th>YC</th><th>RC</th><th>Minutes</th><th>Clean sheets</th><th>Rating</th></tr></thead><tbody>${visible.map((player) => `<tr><td><span class="player-identity">${badge(player)}<span><strong>${esc(player.name)}</strong><small>${esc(player.nationality)} / age ${player.age}</small></span></span></td><td>${esc(player.position)}</td><td>${player.appearances}</td><td>${player.goals}</td><td>${player.assists}</td><td>${player.yellow}</td><td>${player.red}</td><td>${player.minutes}</td><td>${player.cleanSheets}</td><td>${player.rating}</td></tr>`).join('')}</tbody></table></div>`; playersRoot.querySelectorAll('[data-player-filter]').forEach((button) => button.addEventListener('click', () => renderPlayers(button.dataset.playerFilter))); }
renderPlayers();

const teamRoot = document.querySelector('[data-club-team-stats]');
const stats = currentClub.stats;
const coreStats = [['Matches played', stats.played, 'matchdays'], ['Wins', stats.wins, 'victories'], ['Draws', stats.draws, 'shared points'], ['Losses', stats.losses, 'defeats'], ['Goals scored', stats.goalsFor, 'for the club'], ['Goals conceded', stats.goalsAgainst, 'against the club'], ['Clean sheets', stats.cleanSheets, 'shutouts'], ['Possession', `${stats.possession}%`, 'average share']];
const progressStats = [['Possession', stats.possession, 100, '%'], ['Shots', stats.shots, 100, 'attempts'], ['Shots on target', stats.shotsOnTarget, 50, 'on frame'], ['Corners', stats.corners, 50, 'won'], ['Fouls', stats.fouls, 100, 'committed'], ['Yellow cards', stats.yellow, 25, 'bookings'], ['Red cards', stats.red, 5, 'dismissals']];
teamRoot.innerHTML = `${panelTitle('05 / THE NUMBERS', 'Team <em>stats.</em>', 'Season snapshot / 2026-27')}<div class="team-stat-grid">${coreStats.map((item, index) => `<article class="team-stat-card${index === 0 || index === 4 ? ' accent' : ''}"><span>${item[0]}</span><strong>${item[1]}</strong><small>${item[2]}</small></article>`).join('')}</div><article class="profile-card" style="margin-top:15px"><h3>Matchday <em>metrics.</em></h3><div class="stat-progress-grid">${progressStats.map((item) => `<div class="progress-stat"><div><span>${item[0]}</span><strong>${item[1]}${item[3] === '%' ? '%' : ''}</strong></div><div class="progress-track"><span style="width:${Math.min(100, Math.max(5, (item[1] / item[2]) * 100))}%"></span></div></div>`).join('')}</div></article>`;

const history = currentClub.history;
const honours = (history.honours || []).length ? `<section class="history-honours"><div class="history-honours-heading"><span class="history-honours-kicker"><i></i>${esc(history.honoursEyebrow || 'Roll of honour')}</span><h2>${esc(history.honoursTitle || 'Club honours')}</h2></div><div class="history-honours-grid">${history.honours.map((honour) => `<article class="history-honour-card"><svg class="history-honour-trophy" viewBox="0 0 32 32" aria-hidden="true"><path d="M9 5h14v5a7 7 0 0 1-14 0V5Z"></path><path d="M9 8H5v2a7 7 0 0 0 7 7M23 8h4v2a7 7 0 0 1-7 7M16 17v5M11 27h10M13 22h6"></path></svg><strong>${esc(honour.value)}</strong><span>${esc(honour.label)}</span>${honour.detail ? `<small>${esc(honour.detail)}</small>` : ''}</article>`).join('')}</div></section>` : '';
document.querySelector('[data-club-history]').innerHTML = `${panelTitle('06 / THE ARCHIVE', 'Club <em>history.</em>', `Since ${currentClub.founded}`)}${honours}<div class="history-grid"><article class="history-card"><h3>Identity & <em>honours.</em></h3><ul class="history-list"><li><strong>Founded:</strong> ${currentClub.founded} in ${esc(currentClub.city)}</li><li><strong>Previous names:</strong> ${history.previousNames.map(esc).join(' / ')}</li><li><strong>Major trophies:</strong> ${history.trophies.map(esc).join(' / ')}</li><li><strong>Best league finish:</strong> Position ${currentClub.position} in the current season</li></ul></article><article class="history-card"><h3>Famous <em>figures.</em></h3><ul class="history-list"><li><strong>Players:</strong> ${history.famousPlayers.map(esc).join(' / ')}</li><li><strong>Coaches:</strong> ${history.famousCoaches.map(esc).join(' / ')}</li><li><strong>Home:</strong> ${esc(currentClub.stadium)}</li><li><strong>Colors:</strong> ${esc(currentClub.colors)}</li></ul></article><div class="history-timeline">${history.milestones.map((milestone, index) => `<div class="history-milestone"><strong>0${index + 1} / Milestone</strong><span>${esc(milestone)}</span></div>`).join('')}</div><article class="history-card" style="grid-column:1/-1"><h3>Previous <em>seasons.</em></h3><ul class="history-list">${history.previousSeasons.map((season) => `<li>${esc(season)} / profile archived for the club record.</li>`).join('')}</ul></article></div>`;function activatePanel(id, updateUrl = true) { const valid = tabs.some(([key]) => key === id) ? id : 'overview'; document.querySelectorAll('.club-profile-panel').forEach((panel) => { panel.hidden = panel.dataset.panel !== valid; panel.classList.toggle('is-active', panel.dataset.panel === valid); }); document.querySelectorAll('[data-profile-tab]').forEach((tab) => tab.classList.toggle('active', tab.dataset.profileTab === valid)); if (updateUrl) { try { window.history.replaceState({}, '', `${profileUrl}&tab=${encodeURIComponent(valid)}#${valid}`); } catch (error) { window.location.hash = valid; } } }
document.querySelectorAll('[data-profile-tab]').forEach((tab) => tab.addEventListener('click', (event) => { event.preventDefault(); activatePanel(tab.dataset.profileTab); document.querySelector('.club-profile-tabs')?.scrollIntoView({ behavior: 'smooth', block: 'start' }); }));
activatePanel(clubParams.get('tab') || window.location.hash.slice(1) || 'overview', false);

const menuToggle = document.querySelector('.menu-toggle');
const mainNav = document.querySelector('.main-nav');
if (menuToggle && mainNav) { menuToggle.addEventListener('click', () => { const open = mainNav.classList.toggle('open'); menuToggle.classList.toggle('open', open); menuToggle.setAttribute('aria-expanded', String(open)); document.body.classList.toggle('menu-open', open); }); mainNav.querySelectorAll('a').forEach((link) => link.addEventListener('click', () => { mainNav.classList.remove('open'); menuToggle.classList.remove('open'); menuToggle.setAttribute('aria-expanded', 'false'); document.body.classList.remove('menu-open'); })); }
const drawer = document.querySelector('[data-search-drawer]'); const searchTrigger = document.querySelector('[data-search-trigger]'); const searchClose = document.querySelector('[data-search-close]'); const drawerInput = document.querySelector('.search-form input');
if (drawer && searchTrigger && searchClose) { const closeSearch = () => { drawer.classList.remove('open'); drawer.setAttribute('aria-hidden', 'true'); document.body.classList.remove('drawer-open'); }; searchTrigger.addEventListener('click', () => { drawer.classList.add('open'); drawer.setAttribute('aria-hidden', 'false'); window.setTimeout(() => drawerInput?.focus(), 180); }); searchClose.addEventListener('click', closeSearch); drawer.addEventListener('click', (event) => { if (event.target === drawer) closeSearch(); }); document.addEventListener('keydown', (event) => { if (event.key === 'Escape') closeSearch(); }); }
const newsletterForm = document.querySelector('[data-newsletter-form]'); newsletterForm?.addEventListener('submit', (event) => { event.preventDefault(); const button = newsletterForm.querySelector('button'); const note = newsletterForm.querySelector('.form-note'); button.innerHTML = "You're in <span>&check;</span>"; button.disabled = true; if (note) note.textContent = 'Welcome to the clubhouse. Check your inbox for the first whistle.'; });
